// NOTE (mristin):
// Currently, Go does not support self-closing tags,
// see: https://github.com/golang/go/issues/21399.
// We apply the following hack to make the tags self-closing even if they are not.
// This is unsafe in general, but works OK for the limited set of test data that we are
// here dealing with.
//
// The code has been taken from: https://github.com/golang/go/issues/21399#issuecomment-1342730174

// NOTE (mristin):
// The opening tag, tag name plus an optional attribute list (*e.g.*,
// ``xmlns="..."`` on a root element), is captured in the first (and only)
// submatch group so that we do not lose any attributes when we force
// the tag to be self-closing below. The attribute list must not end with
// a slash, as we would otherwise match an already self-closing tag followed
// by the closing tag of its parent, *e.g.*, ``<someBytes /></something>``.
var emptyTagRe = regexp.MustCompile(`<(\w+(?:\s[^>]*[^/>])?)></\w+>`)

func forceSelfClosingTags(text string) string {
	b := []byte(text)
	emptyTagIdxs := emptyTagRe.FindAllSubmatchIndex(b, -1)

	if len(emptyTagIdxs) == 0 {
		return text
	}

	// NOTE (mristin):
	// The matches are walked in order, and the pieces of `b` between them are
	// copied over as they are. Mind that `nb` starts out empty and that `b` is
	// only ever *read*: an earlier version appended into `b[0:idx[0]]`, which
	// writes into `b`'s own backing array, so a document with more than one
	// empty tag came out garbled -- every turn of the loop then indexed into
	// a `b` which the previous turn had already overwritten.
	var nb []byte
	previous := 0

	for _, idx := range emptyTagIdxs {
		// Copy everything since the previous match, then the tag itself --
		// its name and its attributes -- as a self-closing one.
		nb = append(nb, b[previous:idx[0]]...)
		nb = append(nb, fmt.Sprintf("<%s/>", b[idx[2]:idx[3]])...)

		previous = idx[1]
	}

	// Finally, copy everything after the last match.
	nb = append(nb, b[previous:]...)

	return string(nb)
}

var whitespaceBetweenTagsRe = regexp.MustCompile(`>\s+<`)

// Remove all whitespace (including newlines, tabs, and spaces) between XML tags
// without parsing the XML.
func removeWhitespaceBetweenTags(text string) string {
	return whitespaceBetweenTagsRe.ReplaceAllString(text, "><")
}

var whitespaceBeforeAngleBracketsRe = regexp.MustCompile(`\s+>`)
var whitespaceBeforeSelfClosingRe = regexp.MustCompile(`\s+/>`)
var whitespaceAfterAngleBracketsRe = regexp.MustCompile(`<\s+`)

// Remove any whitespace before `>` and `/>` or after `<`
func removeWhitespaceWithinTags(text string) string {
	result := text
	result = whitespaceBeforeAngleBracketsRe.ReplaceAllString(result, ">")
	result = whitespaceBeforeSelfClosingRe.ReplaceAllString(result, "/>")
	result = whitespaceAfterAngleBracketsRe.ReplaceAllString(result, "<")
	return result
}

// Follow the model's XML nesting to recognize string values, including collection
// items. Container whitespace remains available to the existing indentation cleanup.
func xmlTextContext(parent string, name xml.Name) string {
	switch parent {
	case "class:Item":
		switch name {
		case (xml.Name{Space: "https://dummy.com", Local: "texts"}):
			return "content:ListOf_string"
		}
	case "class:Something":
		switch name {
		case (xml.Name{Space: "https://dummy.com", Local: "items"}):
			return "content:ListOf_IItem"
		case (xml.Name{Space: "https://dummy.com", Local: "kind"}):
			return "text"
		case (xml.Name{Space: "https://dummy.com", Local: "numbers"}):
			return "content:ListOf_long"
		case (xml.Name{Space: "https://dummy.com", Local: "texts"}):
			return "content:ListOf_string"
		}
	case "content:ListOf_IItem":
		switch name {
		case (xml.Name{Space: "https://dummy.com", Local: "item"}):
			return "class:Item"
		}
	case "content:ListOf_string":
		switch name {
		case (xml.Name{Space: "https://dummy.com", Local: "v"}):
			return "text"
		}
	case "root":
		switch name {
		case (xml.Name{Space: "https://dummy.com", Local: "item"}):
			return "class:Item"
		case (xml.Name{Space: "https://dummy.com", Local: "something"}):
			return "class:Something"
		}
	}
	return ""
}

// Normalize escaping in character data while retaining the original markup.
// Copying tags verbatim avoids changing namespace declarations or prefixes.
func normalizeXmlTextEscaping(text string) (string, error) {
	decoder := xml.NewDecoder(strings.NewReader(text))
	var result bytes.Buffer
	contexts := []string{"root"}
	for {
		start := decoder.InputOffset()
		token, err := decoder.Token()
		if err == io.EOF {
			return result.String(), nil
		}
		if err != nil {
			return "", err
		}
		if start, ok := token.(xml.StartElement); ok {
			contexts = append(contexts, xmlTextContext(contexts[len(contexts)-1], start.Name))
		}
		if data, ok := token.(xml.CharData); ok {
			// Normalize strings consistently, even if they consist only of whitespace.
			// Keep container indentation available to the existing cleanup.
			if contexts[len(contexts)-1] != "text" && strings.Trim(string(data), " \t\r\n") == "" {
				result.WriteString(text[start:decoder.InputOffset()])
			} else {
				var escaped bytes.Buffer
				if err := xml.EscapeText(&escaped, data); err != nil {
					return "", err
				}
				if contexts[len(contexts)-1] == "text" {
					// Protect spaces as well as tabs and line breaks from the regex cleanup.
					result.WriteString(strings.ReplaceAll(escaped.String(), " ", "&#32;"))
				} else {
					result.Write(escaped.Bytes())
				}
			}
		} else {
			result.WriteString(text[start:decoder.InputOffset()])
		}
		if _, ok := token.(xml.EndElement); ok {
			contexts = contexts[:len(contexts)-1]
		}
	}
}

func TestNormalizeXmlTextEscaping(t *testing.T) {
	cases := []struct {
		name  string
		input string
		want  string
	}{
		{"quotes", `<v>"hello"</v>`, `<v>&#34;hello&#34;</v>`},
		{"quote_references", `<v>&quot;hello&#x22;</v>`, `<v>&#34;hello&#34;</v>`},
		{"apostrophes", `<v>'hello'</v>`, `<v>&#39;hello&#39;</v>`},
		{"tabs", "<v>a\tb</v>", `<v>a&#x9;b</v>`},
		{"tab_reference", `<v>a&#9;b</v>`, `<v>a&#x9;b</v>`},
		{"double_escaping", `<v>&amp;#34;</v>`, `<v>&amp;#34;</v>`},
		{"text_is_not_markup", `<v>&#60;x/&#62;</v>`, `<v>&lt;x/&gt;</v>`},
		{"string_spaces", `<v> hello </v>`, `<v> hello </v>`},
		{"markup", `<p:v xmlns:p='urn:test' a='"'/>`, `<p:v xmlns:p='urn:test' a='"'/>`},
		{"numbers", `<v>1e2</v>`, `<v>1e2</v>`},
		{"indentation", "<r>\n\t<v/>\n</r>", "<r>\n\t<v/>\n</r>"},
		{"whitespace_reference", `<v>&#x9;</v>`, `<v>&#x9;</v>`},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, err := normalizeXmlTextEscaping(c.input)
			if err != nil {
				t.Fatal(err)
			}
			if got != c.want {
				t.Fatalf("Expected %q, got %q", c.want, got)
			}
		})
	}
}

func canonicalizeXmlForComparison(text string) (string, error) {
	text = strings.TrimSpace(text)
	// Escape text before applying the legacy markup cleanup, so a literal
	// '>' in a value can not make the cleanup remove a preceding space.
	text, err := normalizeXmlTextEscaping(text)
	if err != nil {
		return "", err
	}
	text = strings.ReplaceAll(text, "\r", "")
	text = removeWhitespaceBetweenTags(text)
	text = forceSelfClosingTags(text)
	return removeWhitespaceWithinTags(text), nil
}

func TestXmlComparisonPreservesText(t *testing.T) {
	for _, c := range []struct {
		name     string
		expected string
		actual   string
		equal    bool
	}{
		{"equivalent_escaping", `<v>x ></v>`, `<v>x &gt;</v>`, true},
		{"lost_space", `<v>x ></v>`, `<v>x&gt;</v>`, false},
		{"numeric_reference", `<v>x ></v>`, `<v>x &#62;</v>`, true},
		{"extra_space", `<v>x ></v>`, `<v>x  &gt;</v>`, false},
		{"tab_vs_newline", `<v>&#x9;</v>`, `<v>&#xA;</v>`, false},
		{"tab_vs_space", `<v>&#x9;</v>`, `<v>&#32;</v>`, false},
		{"lost_tab", `<v>&#x9;</v>`, `<v></v>`, false},
		{"space_vs_literal_tab", `<v>&#32;</v>`, "<v>\t</v>", false},
	} {
		t.Run(c.name, func(t *testing.T) {
			expected, err := canonicalizeXmlForComparison(c.expected)
			if err != nil {
				t.Fatal(err)
			}
			actual, err := canonicalizeXmlForComparison(c.actual)
			if err != nil {
				t.Fatal(err)
			}
			if (expected == actual) != c.equal {
				t.Fatalf("Unexpected comparison of %q and %q", expected, actual)
			}
		})
	}
}

// Assert that the serialization `other`, as XML document, equals the original
//
//	XML document `that` read from the `source`.
func assertSerializationEqualsDeserialization(
	t *testing.T,
	that string,
	other string,
	source string,
) (ok bool) {
	ok = true

	// NOTE (mristin):
	// The following hack is SUPER ugly and unsafe! However, it works. Given Go's
	// limited support for XML, we gave up on a safer approach :(. We tested
	// the following approaches before applying this hack:
	//  * A round-trip over `encoding/xml`. Failed due to
	//    https://github.com/golang/go/issues/13400.
	//  * Using `aqwari.net/xml/xmltree`. Failed as the special characters in the
	//    element content still has not been de-escaped or consistently escaped in
	//    a round trip.

	canonicalThat, err := canonicalizeXmlForComparison(that)
	if err != nil {
		t.Fatalf("Failed to normalize original XML from %s: %s", source, err)
		return false
	}
	canonicalOther, err := canonicalizeXmlForComparison(other)
	if err != nil {
		t.Fatalf("Failed to normalize serialized XML from %s: %s", source, err)
		return false
	}

	thatLines := strings.Split(canonicalThat, "\n")
	otherLines := strings.Split(canonicalOther, "\n")

	if canonicalThat != canonicalOther {
		b := new(strings.Builder)
		minLines := len(thatLines)
		if minLines > len(otherLines) {
			minLines = len(otherLines)
		}
		for i := 0; i < minLines; i++ {
			if thatLines[i] == otherLines[i] {
				b.WriteString(fmt.Sprintf("           %s\n", thatLines[i]))
			} else {
				b.WriteString(fmt.Sprintf("ORIGINAL   %s\n", thatLines[i]))
				b.WriteString(fmt.Sprintf("SERIALIZED %s\n", otherLines[i]))
				break
			}
		}

		ok = false
		t.Fatalf(
			"The canonicalized XML serialization of the de-serialized instance "+
				"from %s does not equal the canonicalized original XML document:\n"+
				"%s",
			source, b.String(),
		)
		return
	}

	return
}

// Assert that there is a de-serialization error.
//
// If [ourtesting.RecordMode] is set, the de-serialization error is re-recorded
// to `expectedPth`. Otherwise, the error is compared against the golden file
// `expectedPth`.
func assertIsDeserializationErrorAndEqualsExpectedOrRecord(
	t *testing.T,
	err error,
	source string,
	expectedPth string,
) (ok bool) {
	ok = true

	if err == nil {
		ok = false
		t.Fatalf("De-serialization error expected from %s, but got none", source)
		return
	}

	deseriaErr, is := err.(*ourxmlization.DeserializationError)
	if !is {
		ok = false
		t.Fatalf(
			"Expected a de-serialization error, "+
				"but got an error of type %T from %s: %v",
			err, source, err,
		)
		return
	}

	// Add a new line for POSIX systems.
	got := deseriaErr.Error() + "\n"

	if ourtesting.RecordMode {
		parent := filepath.Dir(expectedPth)
		err := os.MkdirAll(parent, os.ModePerm)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to create the directory %s: %s", parent, err.Error(),
				),
			)
		}

		err = os.WriteFile(expectedPth, []byte(got), 0644)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to write to the file %s: %s", expectedPth, err.Error(),
				),
			)
		}
	} else {
		_, err := os.Stat(expectedPth)
		if err != nil {
			ok = false
			t.Fatalf(
				"Failed to stat the file %s: %s; if the file does not exist, "+
					"you probably want to record the test data by "+
					"setting the environment variable %s",
				expectedPth, err.Error(), ourtesting.RecordModeEnvironmentVariableName,
			)
			return
		}

		bb, err := os.ReadFile(expectedPth)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to read from file %s: %s", expectedPth, err.Error(),
				),
			)
		}

		expected := string(bb)

		// NOTE (mristin):
		// Git automatically strips and adds `\r`, so we have to remove it here
		// to obtain a canonical text.
		expected = strings.Replace(expected, "\r", "", -1)

		if expected != got {
			ok = false
			t.Fatalf(
				"What we got differs from the expected in %s. "+
					"We got:\n%s\nWe expected:\n%s",
				expectedPth, got, expected,
			)
			return
		}
	}

	return
}

